from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations


def _quota_intervals(data, capacity, tie):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    if k < 0 or k > len(options):
        return {"error": "impossible"}

    for selected in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue

        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        events = []
        for job in selected:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        valid = True
        for _, delta in sorted(events):
            active += delta
            if active > capacity:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and
                 ((tie == "smallest" and ids < best_ids) or
                  (tie == "largest" and ids > best_ids)))):
            best_value = value
            best_ids = ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_01(data):
    return _quota_intervals(data, 2, "largest")


def _component_02(data):
    return _quota_intervals(data, 1, "smallest")


