def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    constraints = {}
    for name, bounds in data["roots"].items():
        constraints.setdefault(name, []).append(tuple(bounds))

    best_vector = None
    best_assignment = None

    def is_acyclic(edges):
        done = set()
        active = set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for dependency in edges.get(name, ()):
                if not visit(dependency):
                    return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(assigned, current_constraints, edges):
        nonlocal best_vector, best_assignment

        # Constraints may be added to a package that was already assigned.
        for name, version in assigned.items():
            if any(not low <= version <= high
                   for low, high in current_constraints.get(name, ())):
                return

        pending = [name for name in current_constraints if name not in assigned]
        if not pending:
            if not is_acyclic(edges):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_assignment = dict(assigned)
            return

        # Variable ordering is only a search heuristic; all feasible assignments
        # are compared by the specified version vector at completion.
        name = pending[0]
        ranges = current_constraints[name]
        rows = [row for row in packages[name]
                if all(low <= row["version"] <= high for low, high in ranges)
                and row["version"] not in blocked.get(name, [])]
        if name in pins:
            rows = [row for row in rows if row["version"] == pins[name]]

        for row in rows:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = {key: list(value)
                                for key, value in current_constraints.items()}
            next_edges = {key: list(value) for key, value in edges.items()}
            dependencies = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                dependencies.append(dep_name)
                next_constraints.setdefault(dep_name, []).append(
                    (dep["min"], dep["max"]))
            next_edges[name] = dependencies
            search(next_assigned, next_constraints, next_edges)

    search({}, constraints, {})
    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_assignment}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    required_bits = {node: 1 << index for index, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    start_mask = required_bits.get(source, 0)
    initial = (source, start_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full_mask and remaining == 0:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            next_mask = mask | required_bits.get(edge["v"], 0)
            durations = [(edge["duration"], remaining)]
            if remaining:
                discounted = max(1, edge["duration"] - edge.get("discount", 0))
                durations.append((discounted, remaining - 1))

            for duration, next_remaining in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, edge["v"],
                                           next_mask, next_remaining))

    return {"arrival": None}


